<script setup lang="ts">
import { ref, computed } from 'vue'
import { works } from '../../content/works'
import WorkCard from '../components/WorkCard.vue'
import WorkPreview from '../components/WorkPreview.vue'
import AboutSection from '../components/AboutSection.vue'
import { useSeo } from '../seo'
useSeo('个人软件作品集', '师说 Laoshi 是学习、实践与分享中的个人软件作品集，收录课思库、智链中枢、岁岁时光、岁音、岁岁食光小厨房与岁影。终身求知，以诚对话。', '/')
const active = ref('all')
const filters = [{ key: 'all', label: '全部' }, { key: 'desktop', label: '桌面端' }, { key: 'mobile', label: '移动端' }, { key: 'service', label: 'Web 服务' }]
const filtered = computed(() => works.filter(work => active.value === 'all' || work.category === active.value))
const preview = ref<InstanceType<typeof WorkPreview>>()
const platforms = new Set(works.flatMap(work => work.platforms).filter(platform => platform !== 'API').map(platform => platform.startsWith('Web') ? 'Web' : platform)).size
</script>
